def encode(message):
    vowels = "aeiou"
    result = ""
    for char in message:
        if char.isalpha():
            if char.isupper():
                result += char.lower()
            else:
                result += char.upper()
            if char in vowels:
                index = vowels.index(char)
                new_char = vowels[(index + 2) % 5]
                result += new_char.upper() if char.isupper() else new_char.lower()
            else:
                result += char
        else:
            result += char
    return result
