    if n == 1:
        return 1
    max_prime = 1
    while n % 2 == 0:
        max_prime = 2
        n //= 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            max_prime = i
            n //= i
        i += 2
    if n > 1:
        max_prime = n
    return max_prime
