def extract_missing(ranges, start, end):
    ranges = sorted(ranges, key=lambda x: x[0])
    missing = []
    current = start
    for r in ranges:
        if r[0] > current:
            missing.append((current, r[0]))
        current = max(current, r[1])
    if current < end:
        missing.append((current, end))
    return missing
