        return 0
    elif n == 1:
        return 1
    elif n == 2:
        return 1
    else:
        perrin = [0, 1, 1]
        for i in range(3, n + 1):
            perrin.append(perrin[i - 2] + perrin[i - 3])
        return sum(perrin)
